$("#periode").on("change",function(){let e=$(this).val();console.log(e);let a=$("#nik").val();if(a=="")return Swal.fire({title:"Peringatan",text:"Masukan data User terlebih dahulu",icon:"warning"});$.ajax({url:`/api/presensi/riwayat/${a}?periode=${e}`,method:"GET"}).then(t=>{let n=t.data;listKehadiran(n)}).catch(t=>{console.error(t)})});function getStatusMasuk(e){return e=="Masuk Terlambat"?`<p class="text-xs text-left text-yellow-600">${e}</p>`:`<p class="text-xs text-left text-green-600">${e||"-"}</p>`}function getStatusPulang(e){return e=="Pulang Cepat"?`<p class="text-xs text-left text-red-600">${e}</p>`:`<p class="text-xs text-left text-green-600">${e||"-"}</p>`}async function listKehadiran(e){console.log(e);const a=document.getElementById("listKehadiran");a.innerHTML="",e.length==0&&(a.innerHTML="<p class='text-sm text-gray-500'>Tidak ada data.</p>");for(let t of e){const n=new Date(t.date).toLocaleDateString("id-ID",{weekday:"long",year:"numeric",month:"long",day:"numeric"}),s=`
                        <div class="bg-gray-50 p-4 rounded-lg shadow-sm">
                        <span class="text-xs bg-blue-100 text-blue-700 font-medium px-2 py-0.5  rounded">${t.Jnsdn.type}</span>
                            <div class="mb-2 font-medium text-gray-700">${n}</div>
                            <div class="grid grid-cols-1 sm:grid-cols-2 gap-3">
                            <div>
                                <p class="text-sm text-left text-gray-600">Masuk: <span class="font-medium text-gray-800">${t.cekIn?t.cekIn:"-"}</span></p>
                                ${getStatusMasuk(t.statusIn)}
                                <p class="text-xs text-left font-medium">Lokasi:${t.loactionIn?t.loactionIn:"-"}</p>
                                <p class="text-xs text-left font-medium">Ket:${t.keteranganIn?t.keteranganIn:"-"}</p>
                            </div>
                            <div>
                                <p class="text-sm text-left text-gray-600">Pulang: <span class="font-medium text-gray-800">${t.cekOut?t.cekOut:"-"}</span></p>
                                ${getStatusPulang(t.statusOut)}
                                <p class="text-xs text-left font-medium">Lokasi:${t.loactionOut?t.loactionOut:"-"}</p>
                                <p class="text-xs text-left font-medium">Ket:${t.keteranganOut?t.keteranganOut:"-"}</p>
                            </div>
                            </div>
                        </div>
                        `;a.innerHTML+=s}}
